package com.jnapanam.sportszone.notification.provider;
import com.jnapanam.sportszone.notification.model.NotificationChannel;import java.util.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Component;
@Component public class NotificationProviderRegistry{private final Map<NotificationChannel,List<NotificationProvider>> providers=new EnumMap<>(NotificationChannel.class);private final String emailProvider,smsProvider;public NotificationProviderRegistry(List<NotificationProvider> list,@Value("${app.notification.email.provider:smtp}")String emailProvider,@Value("${app.notification.sms.provider:fast2sms}")String smsProvider){this.emailProvider=emailProvider;this.smsProvider=smsProvider;for(NotificationProvider p:list)providers.computeIfAbsent(p.channel(),k->new ArrayList<>()).add(p);}public NotificationProvider provider(NotificationChannel channel){String wanted=switch(channel){case EMAIL->emailProvider;case SMS->smsProvider;default->null;};List<NotificationProvider> candidates=providers.getOrDefault(channel,List.of());if(wanted!=null)return candidates.stream().filter(p->p.name().equalsIgnoreCase(wanted)).findFirst().orElseThrow(()->new IllegalStateException("Notification provider '"+wanted+"' is not installed for "+channel));return candidates.stream().findFirst().orElseThrow(()->new IllegalStateException("No notification provider configured for "+channel));}}
